            TextProperties::SetStyleSheet(pNewStyleSheet, bDontRemoveHardAttr, bBroadcast, bAdjustTextFrameWidthAndHeight);

            // local changes
            SdrEdgeObj& rObj = static_cast<SdrEdgeObj&>(GetSdrObject());
            rObj.ImpSetAttrToEdgeInfo();
